from taf.rfrl.procedures.resources.python.status_check.status_selector.StatusSelector import StatusSelector
from taf.rfrl.procedures.resources.python.status_check.exceptions import InvalidRmodVariant


class Rmod(object):
    __MISSING_IMPLEMENTATION_ERROR_MSG = "{} class has missing implementation of {} method"
    _status_selector = StatusSelector()

    def get_expected_statuses(self, variant):
        """
        Returns expected values of statuses for given variant.
        :param variant: variant of expected statuses, can be 'active', 'online', 'offline', 'disabled', 'locked'
                        'failed' or 'uncommissioned'
        :type variant: str
        :return: dictionary with statuses names as keys and expected statuses values as values
        :rtype: dict(str, str)
        """
        if variant == 'active':
            return self._get_active_statuses()
        elif variant == 'online':
            return self._get_online_statuses()
        elif variant == 'offline':
            return self._get_offline_statuses()
        elif variant == 'disabled':
            return self._get_disabled_statuses()
        elif variant == 'locked':
            return self._get_locked_statuses()
        elif variant == 'failed':
            return self._get_failed_statuses()
        elif variant == 'uncommissioned':
            return self._get_uncommissioned_statuses()
        elif variant == 'degraded':
            return self._get_degraded_statuses()
        elif variant == 'deep_sleep':
            return self._get_deep_sleep_statuses()
        elif variant == 'extreme_deep_sleep':
            return self._get_extreme_deep_sleep_statuses()
        else:
            raise InvalidRmodVariant("Rmod variant must be one of the following:\n['active', 'online', 'offline', 'disabled', locked, 'failed', "
                                     "'uncommissioned', 'degraded', 'deep_sleep', 'extreme_deep_sleep']")

    def _get_active_statuses(self):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__,
            self._get_active_statuses.__name__))

    def _get_online_statuses(self):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__,
            self._get_online_statuses.__name__))

    def _get_offline_statuses(self):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__,
            self._get_offline_statuses.__name__))

    def _get_disabled_statuses(self):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__,
            self._get_disabled_statuses.__name__))

    def _get_locked_statuses(self):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__,
            self._get_locked_statuses.__name__))

    def _get_failed_statuses(self):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__,
            self._get_failed_statuses.__name__))

    def _get_uncommissioned_statuses(self):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__,
            self._get_uncommissioned_statuses.__name__))

    def _get_degraded_statuses(self):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__,
            self._get_degraded_statuses.__name__))

    def _get_deep_sleep_statuses(self):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__,
            self._get_deep_sleep_statuses.__name__))

    def _get_extreme_deep_sleep_statuses(self):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__,
            self._get_extreme_deep_sleep_statuses.__name__))
